CREATE TRIGGER member_capacity BEFORE INSERT ON memberships WHEN (SELECT COUNT(*) FROM memberships WHERE organization_id=NEW.organization_id)>=20 AND NOT EXISTS (SELECT 1 FROM memberships WHERE organization_id=NEW.organization_id AND user_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'Member capacity reached'); END;
CREATE TRIGGER monitor_valid_insert BEFORE INSERT ON monitors WHEN NEW.method NOT IN ('GET','HEAD') OR NEW.interval NOT IN (300,600,900,1800,3600) OR NEW.timeout NOT BETWEEN 1000 AND 10000 OR NEW.expected_min NOT BETWEEN 100 AND 599 OR NEW.expected_max NOT BETWEEN NEW.expected_min AND 599 OR NEW.failure_threshold NOT BETWEEN 1 AND 5 OR NEW.recovery_threshold NOT BETWEEN 1 AND 5 OR NEW.status NOT IN ('pending','operational','degraded','down','paused','unknown') BEGIN SELECT RAISE(ABORT,'Invalid monitor configuration'); END;
CREATE TRIGGER monitor_valid_update BEFORE UPDATE ON monitors WHEN NEW.method NOT IN ('GET','HEAD') OR NEW.interval NOT IN (300,600,900,1800,3600) OR NEW.timeout NOT BETWEEN 1000 AND 10000 OR NEW.expected_min NOT BETWEEN 100 AND 599 OR NEW.expected_max NOT BETWEEN NEW.expected_min AND 599 OR NEW.failure_threshold NOT BETWEEN 1 AND 5 OR NEW.recovery_threshold NOT BETWEEN 1 AND 5 OR NEW.status NOT IN ('pending','operational','degraded','down','paused','unknown') BEGIN SELECT RAISE(ABORT,'Invalid monitor configuration'); END;
CREATE TRIGGER incident_valid_insert BEFORE INSERT ON incidents WHEN NEW.status NOT IN ('investigating','identified','monitoring','resolved') OR NEW.severity NOT IN ('critical','major','minor') OR NEW.source NOT IN ('system','manual') BEGIN SELECT RAISE(ABORT,'Invalid incident'); END;
CREATE TRIGGER incident_valid_update BEFORE UPDATE OF status ON incidents WHEN NEW.status NOT IN ('investigating','identified','monitoring','resolved') OR (OLD.status='resolved' AND NEW.status!='resolved') BEGIN SELECT RAISE(ABORT,'Invalid incident transition'); END;
CREATE TRIGGER notification_preference AFTER INSERT ON notifications BEGIN
  INSERT OR IGNORE INTO notification_reads(notification_id,user_id) SELECT NEW.id,user_id FROM memberships WHERE organization_id=NEW.organization_id AND notifications=0;
END;
